package com.happybananas.tracezilla.shopify;
import com.fasterxml.jackson.databind.JsonNode; import com.happybananas.tracezilla.shared.*; import java.util.*;
public final class ShopifyCatalog implements CatalogReader {
  private final ShopifyClient client; public ShopifyCatalog(ShopifyClient client){this.client=client;}
  public List<CatalogItem> read() throws Exception {var items=new ArrayList<CatalogItem>();for(var value:readVariants()){var sku=value.path("sku").asText("").trim();if(!sku.isEmpty())items.add(new CatalogItem(sku,value.path("id").asText(""),value.path("displayName").asText(null)));}return items;}
  public List<JsonNode> readVariants() throws Exception { var items=new ArrayList<JsonNode>(); String after=null; do { var variables=new HashMap<String,Object>();variables.put("first",250);variables.put("after",after); var connection=client.graphql(GetProductVariants.DOCUMENT,variables).path("data").path("productVariants"); if(!connection.path("nodes").isArray())throw new IllegalStateException("Shopify response is missing productVariants."); for(JsonNode value:connection.path("nodes"))items.add(value.deepCopy()); if(!connection.path("pageInfo").path("hasNextPage").asBoolean())break; after=connection.path("pageInfo").path("endCursor").asText("");if(after.isEmpty())throw new IllegalStateException("Shopify pagination is missing an end cursor."); }while(true);return items; }
}
